  .ctl{display:grid;grid-template-columns:118px 1fr 62px;align-items:center;gap:8px;margin:5px 0}
  .ctl label{font-size:10.5px;color:#D8E6EE}
  .ctl output{font-size:10px;color:var(--accent);text-align:right;font-variant-numeric:tabular-nums}
