  .bar{height:8px;border-radius:4px;background:#123049;overflow:hidden;margin:4px 0 2px}
  .bar>div{height:100%;width:0%;background:linear-gradient(90deg,#0E5A34,#2FE08C,#DAFF33);transition:width .15s}
  .ro-cap{font-size:8.5px;color:var(--muted)}

  @media (max-width:980px){
    #app{height:auto;max-height:none}
    main{grid-template-columns:1fr}
    #schematicPanel{height:70vw;min-height:380px}
    header{flex-direction:column;height:auto;align-items:flex-start;padding:4px 0}
    .toggle{align-self:stretch}
    .toggle button{flex:1}
  }
</style>
