        <div class="ctl"><label for="sR2">R2 (log)</label><input type="range" id="sR2" min="0" max="1000" step="1" value="500"><output id="oR2">1.00 kΩ</output></div>
        <div class="ctl"><label for="sRV1">RV1 value (log)</label><input type="range" id="sRV1" min="0" max="1000" step="1" value="500"><output id="oRV1">10.0 kΩ</output></div>
        <div class="ctl"><label for="sPos">RV1 wiper position</label><input type="range" id="sPos" min="0" max="100" step="1" value="50"><output id="oPos">50 %</output></div>
