<script>
"use strict";
/* ============================================================
   LED strung across a ±12 V bipolar supply
   Nodal analysis with iterated LED conductance.
   ============================================================ */

var WIRE = '#C1C1FF', ACCENT = '#DAFF33', MUTE = '#8FB3C7', RED = '#FF6B6B';

/* ---------- global simulation state ---------- */
var state = {
  mode: 'fixed',                     // start in Fixed
  values: { B1: 12, B2: 12, R1: 1000, R2: 1000, RV1: 10000 },
  position: { RV1: 0.5 },
  ledBurnt: false,
  ledOn: false,
  selectedNet: null
};

var NET_INFO = {
  vcc: { name: 'vcc', desc: '+12 V rail' },
  gnd: { name: 'gnd', desc: 'centre tap · 0 V reference' },
  vee: { name: 'vee', desc: '−12 V rail' },
  n1:  { name: 'n1',  desc: 'R1 / LED1 node' },
  n2:  { name: 'n2',  desc: 'LED1 / R2 node' },
  vin: { name: 'vin', desc: 'RV1 wiper · ±VIN terminal' }
};

/* ---------- small dense linear solver (Gaussian elimination) ---------- */
function solveMatrix(A, b) {
  var n = b.length, i, r, c, col, piv, f, tmp;
  for (col = 0; col < n; col++) {
    piv = col;
    for (r = col + 1; r < n; r++) if (Math.abs(A[r][col]) > Math.abs(A[piv][col])) piv = r;
    if (piv !== col) {
      tmp = A[piv]; A[piv] = A[col]; A[col] = tmp;
      tmp = b[piv]; b[piv] = b[col]; b[col] = tmp;
    }
    if (Math.abs(A[col][col]) < 1e-12) A[col][col] = 1e-12;
    for (r = col + 1; r < n; r++) {
      f = A[r][col] / A[col][col];
      if (f === 0) continue;
      for (c = col; c < n; c++) A[r][c] -= f * A[col][c];
      b[r] -= f * b[col];
    }
  }
  var x = new Array(n), s;
  for (i = n - 1; i >= 0; i--) {
    s = b[i];
    for (c = i + 1; c < n; c++) s -= A[i][c] * x[c];
    x[i] = s / A[i][i];
  }
  return x;
}

/* ---------- circuit solve ---------- */
function compute() {
  var v = state.values, p = state.position.RV1;
  var vf = state.mode === 'fixed' ? 2.1 : 2.0;         // fixed sheet labels green LED, Vf≈2.1 V; drawn sheet: unidentified → 2.0 V
  var rTop = Math.max((1 - p) * v.RV1, 0.01);
  var rBot = Math.max(p * v.RV1, 0.01);
  var nets = ['vcc', 'vee', 'n1', 'n2', 'vin'];        // gnd is the reference
  var idx = {}; nets.forEach(function (n, i) { idx[n] = i; });
  var n = nets.length;

  function build(ledOn, ledBurnt) {
    var A = [], b = [], i, j;
    for (i = 0; i < n; i++) { A.push(new Array(n).fill(0)); b.push(0); }
    function g(a, b_, gg) {
      var ia = a === 'gnd' ? -1 : idx[a], ib = b_ === 'gnd' ? -1 : idx[b_];
      if (ia >= 0) A[ia][ia] += gg;
      if (ib >= 0) A[ib][ib] += gg;
      if (ia >= 0 && ib >= 0) { A[ia][ib] -= gg; A[ib][ia] -= gg; }
    }
    function src(plus, minus, emf, rint) {
      var gg = 1 / rint, ii = emf * gg;
      g(plus, minus, gg);
      if (plus !== 'gnd') b[idx[plus]] += ii;
      if (minus !== 'gnd') b[idx[minus]] -= ii;
    }
    src('vcc', 'gnd', v.B1, 0.2);    // B1: plus at vcc, 0.2 Ω internal
    src('gnd', 'vee', v.B2, 0.2);    // B2: plus at gnd, minus at vee
    g('vcc', 'vin', 1 / rTop);       // pot upper section
    g('vin', 'vee', 1 / rBot);       // pot lower section
    g('vcc', 'n1', 1 / v.R1);
    g('n2', 'vee', 1 / v.R2);
    if (!ledBurnt) {
      if (ledOn) { g('n1', 'n2', 0.1); b[idx.n1] += vf * 0.1; b[idx.n2] -= vf * 0.1; }
      else g('n1', 'n2', 1e-9);
    }
    var x = solveMatrix(A, b);
    var V = { gnd: 0 };
    nets.forEach(function (nn, i) { V[nn] = x[i]; });
    return V;
  }

  var ledOn = state.ledOn, V = null, vd = 0, onFinal = false, iter;
  for (iter = 0; iter < 12; iter++) {
    V = build(ledOn, state.ledBurnt);
    vd = V.n1 - V.n2;
    var newOn = state.ledBurnt ? false : (vd > vf);
    onFinal = newOn;
    if (newOn === ledOn) { ledOn = newOn; break; }
    ledOn = newOn;
  }
  state.ledOn = ledOn;
  var iLed = state.ledBurnt ? 0 : (onFinal ? Math.max(0, (vd - vf) / 10) : 0);

  if (!state.ledBurnt && iLed > 0.030) {   // over 30 mA → burnt out, becomes open
    state.ledBurnt = true;
    V = build(false, true);
    vd = V.n1 - V.n2; iLed = 0; onFinal = false; state.ledOn = false;
  }

  var iB1 = (v.B1 - V.vcc) / 0.2;            // delivered out of the + terminal
  var iB2 = (v.B2 - (0 - V.vee)) / 0.2;
  var iR1 = (V.vcc - V.n1) / v.R1;
  var iR2 = (V.n2 - V.vee) / v.R2;
  var iPotTop = (V.vcc - V.vin) / rTop;
  var brightness = Math.max(0, Math.min(1, iLed / 0.02));

  return {
    V: V, vf: vf, onFinal: onFinal, iLed: iLed,
    iB1: iB1, iB2: iB2, iR1: iR1, iR2: iR2,
    iPot: iPotTop, iString: iR1, brightness: brightness
  };
}

/* ---------- formatting ---------- */
function fmtV(x) {
  var a = Math.abs(x);
  if (a < 1) return (x * 1000).toFixed(0) + ' mV';
  return x.toFixed(2) + ' V';
}
function fmtI(x) {
  var a = Math.abs(x);
  if (a < 1e-6) return '0.00 mA';
  if (a < 1e-3) return (x * 1e6).toFixed(1) + ' µA';
  if (a < 1) return (x * 1e3).toFixed(2) + ' mA';
  return x.toFixed(3) + ' A';
}
function fmtR(x) {
  if (x >= 1000) { var k = x / 1000; return (k >= 100 ? k.toFixed(0) : k.toFixed(k < 10 ? 2 : 1)).replace(/\.?0+$/, '') + ' kΩ'; }
  return x.toFixed(0) + ' Ω';
}

/* ---------- schematic geometry ---------- */
var TOP = 64, BOT = 576, POTX = 84, STRX = 470, BATX = 690;

var FLOWS = [
  { pts: [[BATX,112],[BATX,TOP],[STRX,TOP]], cur: function (S) { return S.iB1; } },
  { pts: [[STRX,TOP],[POTX,TOP]],             cur: function (S) { return S.iPot; } },
  { pts: [[POTX,TOP],[POTX,120]],             cur: function (S) { return S.iPot; } },
  { pts: [[POTX,470],[POTX,BOT],[STRX,BOT]],  cur: function (S) { return S.iPot; } },
  { pts: [[STRX,BOT],[BATX,BOT],[BATX,366]],  cur: function (S) { return S.iB2; } },
  { pts: [[STRX,TOP],[STRX,272]],             cur: function (S) { return S.iString; } },
  { pts: [[STRX,272],[STRX,306]],             cur: function (S) { return S.iString; } },
  { pts: [[STRX,306],[STRX,BOT]],             cur: function (S) { return S.iString; } },
  { pts: [[BATX,330],[BATX,258]],             cur: function (S) { return S.iB2; } },
  { pts: [[BATX,258],[BATX,148]],             cur: function (S) { return S.iB1; } }
];

var svg = document.getElementById('schem');
var tip = document.getElementById('tooltip');
var netBar = document.getElementById('netBar');
var burntNote = document.getElementById('burntNote');
var lastSolve = null;

/* ---------- SVG construction ---------- */
function esc(s) { return String(s).replace(/&/g,'&amp;').replace(/</g,'&lt;'); }

function render() {
  var S = compute();
  lastSolve = S;
  var v = state.values, p = state.position.RV1, drawn = state.mode === 'drawn';
  var V = S.V, sel = state.selectedNet;
  var yw = 120 + (1 - p) * 350;             // wiper height: p=1 → top

  var vis = [], hits = [], parts = [], ann = [];

  function cond(pts, net, w) {
    var s = sel === net;
    var d = pts.map(function (q, i) { return (i ? 'L' : 'M') + q[0].toFixed(1) + ' ' + q[1].toFixed(1); }).join(' ');
    vis.push('<path class="wire" data-net="' + net + '" d="' + d + '" stroke="' + (s ? ACCENT : WIRE) +
      '" stroke-width="' + (s ? 3.4 : (w || 2.4)) + '" fill="none" stroke-linecap="round" stroke-linejoin="round"/>');
    hits.push('<path data-net="' + net + '" d="' + d + '" stroke="#000" stroke-opacity="0" stroke-width="17" fill="none" pointer-events="stroke"/>');
  }
  function dot(x, y, net) {
    vis.push('<circle data-net="' + net + '" cx="' + x + '" cy="' + y + '" r="3.7" fill="' + (sel === net ? ACCENT : WIRE) + '"/>');
  }
  function txt(x, y, str, cls, anchor, size, weight) {
    return '<text x="' + x + '" y="' + y + '"' +
      (cls ? ' class="' + cls + '"' : '') +
      ' text-anchor="' + (anchor || 'start') + '"' +
      (size ? ' style="font-size:' + size + 'px"' : '') +
      (weight ? ' style="font-weight:' + weight + '"' : '') + '>' + str + '</text>';
  }

  /* === conductor runs (clickable nets) === */
  cond([[POTX, TOP], [BATX, TOP]], 'vcc', 2.6);
  cond([[POTX, TOP], [POTX, 120]], 'vcc');
  cond([[STRX, TOP], [STRX, 96]], 'vcc');
  cond([[BATX, TOP], [BATX, 112]], 'vcc');

  cond([[POTX, BOT], [BATX, BOT]], 'vee', 2.6);
  cond([[POTX, 470], [POTX, BOT]], 'vee');
  cond([[STRX, 490], [STRX, BOT]], 'vee');
  cond([[BATX, 366], [BATX, BOT]], 'vee');

  cond([[STRX, 156], [STRX, 272]], 'n1');
  cond([[STRX, 306], [STRX, 430]], 'n2');
  cond([[BATX, 148], [BATX, 330]], 'gnd');
  cond([[BATX, 258], [744, 258]], 'gnd');

  // wiper lead / stub
  var vinEnd = drawn ? 272 : 206;
  cond([[152, yw], [vinEnd, yw]], 'vin');

  // dangling stubs (as drawn only) — open circuits, they drive nothing
  if (drawn) {
    cond([[STRX, 205], [268, 205]], 'n1');
    cond([[STRX, 392], [292, 392]], 'n2');
    cond([[BATX, 258], [548, 258]], 'gnd');
  }

  /* === junction dots === */
  dot(STRX, TOP, 'vcc'); dot(STRX, BOT, 'vee'); dot(BATX, 258, 'gnd');
  if (drawn) { dot(STRX, 205, 'n1'); dot(STRX, 392, 'n2'); }

  /* === RV1 potentiometer === */
  var rp = '';
  rp += '<g class="part" data-part="RV1">';
  rp += '<rect class="part-hit" x="58" y="112" width="150" height="366" fill="rgba(0,0,0,0)"/>';
  rp += '<rect class="body" x="62" y="120" width="44" height="350" rx="3" fill="#07334E" stroke="' + WIRE + '" stroke-width="2.2"/>';
