/* ---------- current-flow dots ---------- */
var flowState = FLOWS.map(function () { return { off: Math.random() * 72 }; });
var lastT = performance.now();

function pathPoint(pts, d) {
  var i, L, acc = 0;
  for (i = 0; i < pts.length - 1; i++) {
    var dx = pts[i + 1][0] - pts[i][0], dy = pts[i + 1][1] - pts[i][1];
    L = Math.hypot(dx, dy);
    if (d <= acc + L) {
      var t = L === 0 ? 0 : (d - acc) / L;
      return [pts[i][0] + dx * t, pts[i][1] + dy * t];
    }
    acc += L;
  }
  return pts[pts.length - 1];
}
function pathLen(pts) {
  var L = 0, i;
  for (i = 0; i < pts.length - 1; i++) L += Math.hypot(pts[i + 1][0] - pts[i][0], pts[i + 1][1] - pts[i][1]);
  return L;
}

function tick(t) {
  var dt = Math.min(0.05, (t - lastT) / 1000); lastT = t;
  var g = document.getElementById('dots');
  if (g && lastSolve) {
    var S = lastSolve, out = [];
    for (var i = 0; i < FLOWS.length; i++) {
      var f = FLOWS[i], I = f.cur(S);
      if (I == null || Math.abs(I) < 2e-6) continue;
      var len = pathLen(f.pts);
      var speed = 18 + I * 3800;
      var sp = flowState[i];
      sp.off = (sp.off + speed * dt) % 72;
      for (var d = sp.off; d < len; d += 72) {
        var q = pathPoint(f.pts, d);
        out.push('<circle cx="' + q[0].toFixed(1) + '" cy="' + q[1].toFixed(1) + '" r="3.1" fill="' + ACCENT + '" opacity="0.95"/>');
      }
    }
    g.innerHTML = out.join('');
  }
  requestAnimationFrame(tick);
}

