window.__sim = {
  setMode: function (mode) { setMode(mode); },
  setSwitch: function (id, closed) { void id; void closed; /* this netlist contains no switches or buttons */ },
  setValue: function (id, value) {
    var v = Number(value);
    if (!isFinite(v)) return;
    switch (id) {
      case 'B1': state.values.B1 = Math.min(18, Math.max(0.5, v)); break;
      case 'B2': state.values.B2 = Math.min(18, Math.max(0.5, v)); break;
      case 'R1': state.values.R1 = Math.min(1e6, Math.max(1, v)); break;
      case 'R2': state.values.R2 = Math.min(1e6, Math.max(1, v)); break;
      case 'RV1': state.values.RV1 = Math.min(1e6, Math.max(10, v)); break;
      case 'LED1': return;                     // LED has no adjustable scalar in this model
      default: return;
    }
    syncSliderOutputs(); render();
  },
  setPosition: function (id, p) {
    if (id !== 'RV1') return;
    var x = Number(p);
    if (!isFinite(x)) return;
    state.position.RV1 = Math.min(1, Math.max(0, x));
    syncSliderOutputs(); render();
